verifyCmd:
node <<'VERIFYJS'
const g = require('./globMatch.js');
const t = (p, s, want, m) => { if (g(p, s) !== want) { console.error('FAIL', m, p, s); process.exit(1); } };
t('*.js', 'a.js', true, 'star');
t('*.js', 'a/b.js', false, 'star must not cross /');
t('**/*.js', 'a/b/c.js', true, 'globstar');
t('**/*.js', 'c.js', true, 'globstar matches zero dirs');
t('a/**/b', 'a/b', true, 'a/**/b matches a/b');
t('a/**/b', 'a/x/y/b', true, 'a/**/b matches nested');
t('?.js', 'a.js', true, 'question');
t('?.js', 'ab.js', false, 'question is exactly one');
t('[abc].js', 'b.js', true, 'class');
t('[a-z].js', 'q.js', true, 'range');
t('[!abc].js', 'd.js', true, 'negated class');
t('[!abc].js', 'a.js', false, 'negated class excludes');
t('\\*.js', '*.js', true, 'escaped star literal');
t('\\*.js', 'a.js', false, 'escaped star is not a wildcard');
t('a*c', 'abc', true, 'mid star');
t('a*c', 'ac', true, 'star matches empty');
try { g('[abc', 'x'); console.error('no throw on unterminated class'); process.exit(1); } catch (e) {}
try { g('a\\', 'a'); console.error('no throw on trailing escape'); process.exit(1); } catch (e) {}
console.log('ok');
VERIFYJS
